import React, { useState, useEffect } from "react";
import axios from "axios";
import {
  FaPlay,
  FaCheckCircle,
  FaQuestionCircle
} from "react-icons/fa";
import AppShell from "./ui/AppShell";
import Panel from "./ui/Panel";
import AlertBox from "./AlertBox";
import "./theme.css";

function QuizStudent() {
  const userId = localStorage.getItem("user_id");

  const [subjectCode, setSubjectCode] = useState("");
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState({});
  const [score, setScore] = useState(null);
  const [alert, setAlert] = useState(null);

  const loadQuiz = async () => {
    try {
      const res = await axios.get(
        `http://127.0.0.1:8000/get-questions/${subjectCode}`
      );
      setQuestions(res.data.questions || []);
    } catch (err) {
      setAlert({ message: "No quiz found", type: "error" });
    }
  };

  const handleSubmit = async () => {
    try {
      const res = await axios.post("http://127.0.0.1:8000/submit-quiz", {
        user_id: userId,
        answers: answers
      });

      setScore(res.data.score);
      setAlert({ message: "Quiz submitted!", type: "success" });
    } catch (err) {
      setAlert({ message: "Submission failed", type: "error" });
    }
  };

  return (
    <AppShell
      title="Take Quiz"
      subtitle="Attempt quiz and test your knowledge."
      action={<span className="badge badge-purple">Student Quiz</span>}
    >
      {alert && <AlertBox message={alert.message} type={alert.type} />}

      <Panel title="Start Quiz">
        <input
          className="input"
          placeholder="Enter Subject Code"
          value={subjectCode}
          onChange={(e) => setSubjectCode(e.target.value)}
        />

        <button className="btn btn-primary" onClick={loadQuiz}>
          <FaPlay /> Load Quiz
        </button>
      </Panel>

      {questions.length > 0 && (
        <Panel title="Questions">
          {questions.map((q, index) => (
            <div className="quiz-card" key={q.id}>
              <h4>
                {index + 1}. {q.question}
              </h4>

              {["A", "B", "C", "D"].map((opt) => (
                <label key={opt}>
                  <input
                    type="radio"
                    name={`q-${q.id}`}
                    value={opt}
                    onChange={() =>
                      setAnswers({ ...answers, [q.id]: opt })
                    }
                  />
                  {q[`option_${opt.toLowerCase()}`]}
                </label>
              ))}
            </div>
          ))}

          <button className="btn btn-success" onClick={handleSubmit}>
            <FaCheckCircle /> Submit Quiz
          </button>
        </Panel>
      )}

      {score !== null && (
        <Panel title="Result">
          <h2>Your Score: {score}</h2>
        </Panel>
      )}
    </AppShell>
  );
}

export default QuizStudent;
